source /etc/network_turbo && source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && export REQUESTS_CA_BUNDLE=/etc/ssl/certs/ca-certificates.crt && export SSL_CERT_FILE=/etc/ssl/certs/ca-certificates.crt && python3 -c "
import json, urllib.request

# Download aggregate metrics for all 9 seeds + original
results = {}
for seed in range(0, 10):
    if seed == 0:
        model_dir = 'EleutherAI__pythia-410m'
    else:
        model_dir = f'EleutherAI__pythia-410m-seed{seed}'

    # Try different result files to find LAMBADA and ARC-Easy
    base_url = f'https://huggingface.co/datasets/EleutherAI/polypythias-evals/resolve/main/pythia-410m-seed{seed}/step143000/{model_dir}'

    for ts in ['2024-08-19T15-13-00.525301', '2024-08-19T16-21-10.545010', '2024-08-20T12-53-30.471558', '2024-09-10T11-27-05.800186', '2024-09-10T12-47-18.832774', '2024-07-08T06-47-35.937976']:
        url = f'{base_url}/results_{ts}.json'
        try:
            r = urllib.request.urlopen(url, timeout=10)
            data = json.loads(r.read())
            res = data.get('results', {})
            lambada = res.get('lambada_openai', {}).get('acc,none')
            arc = res.get('arc_easy', {}).get('acc,none')
            if lambada or arc:
                results[f'seed{seed}'] = {'lambada_openai': lambada, 'arc_easy': arc, 'file': ts}
                print(f'seed{seed}: LAMBADA={lambada}, ARC-Easy={arc}')
                break
        except:
            continue
    else:
        print(f'seed{seed}: no matching results found')

print(f'\\nTotal: {len(results)} seeds with data')
" 2>&1 | tail -20
